// FUNCTION: BFME2 0x000B1A37 size=522 name=?doDrawModule@W3DDebrisDraw@@UAEXPBVMatrix3D@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void W3DDebrisDraw::doDrawModule(const Matrix3D *transformMtx)
{
	if (m_renderObject == NULL)
		return;

	const Matrix3D *renderMtx;
	Matrix3D scaledMtx;
	if (getDrawable()->m_instanceScale != 1.0f)
	{
		scaledMtx = *transformMtx;
		Real scale = getDrawable()->m_instanceScale;
		// Only the rotation part is scaled; the translation column is left alone.
		scaledMtx.Row[0][0] *= scale;
		scaledMtx.Row[1][0] *= scale;
		scaledMtx.Row[2][0] *= scale;
		scaledMtx.Row[0][1] *= scale;
		scaledMtx.Row[1][1] *= scale;
		scaledMtx.Row[2][1] *= scale;
		scaledMtx.Row[0][2] *= scale;
		scaledMtx.Row[1][2] *= scale;
		scaledMtx.Row[2][2] *= scale;
		renderMtx = &scaledMtx;
		m_renderObject->Set_ObjectScale(getDrawable()->m_instanceScale);
	}
	else
		renderMtx = transformMtx;
	m_renderObject->Set_Transform(*renderMtx);

	// Advance FINAL once the debris has landed, otherwise move on when the animation ends.
	Int prevState = m_state;
	Object *obj = getDrawable()->m_object;
	if (m_state != FINAL && obj && !obj->isAboveTerrain() && m_frames > 3)
		m_state = FINAL;
	else if (m_state < FINAL && isAnimationComplete(m_renderObject))
		++m_state;

	HAnimClass *anim = m_anims[m_state];
	if (anim)
	{
		if (anim != m_renderObject->Peek_Animation() || prevState != m_state)
		{
			static const RenderObjClass::AnimMode TheAnimModes[STATECOUNT] =
			{
				RenderObjClass::ANIM_MODE_ONCE, RenderObjClass::ANIM_MODE_LOOP, RenderObjClass::ANIM_MODE_ONCE
			};
			RenderObjClass::AnimMode mode = TheAnimModes[m_state];
			if (m_state == FINAL)
			{
				if (m_fxFinal)
					FXList::doFXPos(m_fxFinal, getDrawable()->getPosition(), getDrawable()->getTransformMatrix(), 0.0f, NULL);
				if (m_finalStop)
					mode = RenderObjClass::ANIM_MODE_MANUAL;
			}
			m_renderObject->Set_Animation(anim, 0.0f, mode);
		}
	}
	++m_frames;
}

