// FUNCTION: BFME2 0x000B1CE2 size=225 name=??1W3DDebrisDraw@@MAE@XZ evidence=N:ledger tier=B hypothesis:cohesion
W3DDebrisDraw::~W3DDebrisDraw()
{
	if (TheW3DShadowManager && m_shadow)
	{
		TheW3DShadowManager->removeShadow(m_shadow);
		m_shadow = NULL;
	}

	if (m_renderObject)
	{
		W3DDisplay::m_3DScene->Remove_Render_Object(m_renderObject);
		if (m_renderObject)
		{
			m_renderObject->Release_Ref();
			m_renderObject = NULL;
		}
		m_renderObject = NULL;
	}

	for (Int i = 0; i < STATECOUNT; ++i)
	{
		if (m_anims[i])
		{
			m_anims[i]->Release_Ref();
			m_anims[i] = NULL;
		}
		m_anims[i] = NULL;
	}
}

// FUNCTION: BFME2 0x000B1DC3 size=268 name=?xfer@W3DDebrisDraw@@MAEXPAVXfer@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void W3DDebrisDraw::xfer(Xfer *xfer)
{
	DrawModule::xfer(xfer);
	if (xfer->IsLightCRC())
		return;

	xfer->Version1();
	*xfer == m_modelName;
	*xfer == m_modelColor;
	if (xfer->IsLoading())
		setModelName(m_modelName, m_modelColor, (ShadowType)0);

	*xfer == m_animInitial;
	*xfer == m_animFlying;
	*xfer == m_animFinal;
	if (xfer->IsLoading())
		setAnimNames(m_animInitial, m_animFlying, m_animFinal, NULL);

	*xfer == m_state;
	*xfer == m_frames;
	*xfer == m_finalStop;
}
